std::istringstream in("1\n5 5\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("10\n"));

std::istringstream in("2\n-1 -1\n-5 9\n");
